{
  "explanation": "The sine graph is wavy because sine is literally the vertical height of a point moving around a unit circle. As the angle θ increases at a steady rate, that point goes up, comes back down, goes below the axis, and rises again—so the y-coordinate oscillates smoothly between −1 and 1, tracing out the familiar wave.",
  "manimCode": "const circleCenter = [-3.5, 0, 0];
const radius = 1.5;

const circle = new Circle({ radius: radius, color: WHITE });
circle.moveTo(circleCenter);

const hAxis = new Line({ start: [-5.3, 0, 0], end: [-1.7, 0, 0], color: GRAY });
const vAxis = new Line({ start: [-3.5, -1.8, 0], end: [-3.5, 1.8, 0], color: GRAY });

const ax = new Axes({
  xRange: [0, 2 * Math.PI, Math.PI / 2],
  yRange: [-1.5, 1.5, 0.5],
  xLength: 6.5,
  yLength: 3,
  tips: false
});
ax.shift([2.2, 0, 0]);

const sineCurve = ax.plot(x => Math.sin(x), { color: BLUE, numSamples: 200 });

let theta = 0.8;

const radiusLine = new Polygon({ vertices: [circleCenter, circleCenter], color: YELLOW });
radiusLine.setStrokeWidth(3).setFillOpacity(0);

const heightSeg = new Polygon({ vertices: [circleCenter, circleCenter], color: GREEN });
heightSeg.setStrokeWidth(3).setFillOpacity(0);

const connectSeg = new Polygon({ vertices: [circleCenter, circleCenter], color: GRAY });
connectSeg.setStrokeWidth(1.5).setFillOpacity(0);

const movingDot = new Dot({ point: circleCenter, color: YELLOW });
const sineDot = new Dot({ point: ax.c2p(0, 0), color: YELLOW });
const originDot = new Dot({ point: circleCenter, color: WHITE });

const title = new Text({ text: 'sin(θ) = height on the unit circle', color: WHITE, fontSize: 28 });
title.moveTo([0, 3.3, 0]);

const thetaLabel = new MathTex({ latex: '\\theta' });
await thetaLabel.waitForRender();
thetaLabel.scale(0.7);

const sinLabel = new MathTex({ latex: 'y = \\sin(\\theta)' });
await sinLabel.waitForRender();
sinLabel.scale(0.75);
sinLabel.moveTo([2.5, -2.3, 0]);

function updateVisuals() {
  const cx = circleCenter[0];
  const cy = circleCenter[1];
  const px = cx + radius * Math.cos(theta);
  const py = cy + radius * Math.sin(theta);

  movingDot.moveTo([px, py, 0]);
  radiusLine.setVertices([circleCenter, [px, py, 0]]);
  heightSeg.setVertices([[px, cy, 0], [px, py, 0]]);

  const tShow = ((theta % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
  const sp = ax.c2p(tShow, Math.sin(theta));
  sineDot.moveTo(sp);
  connectSeg.setVertices([[px, py, 0], sp]);

  const midAngle = theta / 2;
  const labelR = 0.55;
  thetaLabel.moveTo([
    cx + labelR * Math.cos(midAngle),
    cy + labelR * Math.sin(midAngle),
    0
  ]);
}

scene.add(hAxis, vAxis, circle, ax, sineCurve);
scene.add(radiusLine, heightSeg, connectSeg);
scene.add(originDot, movingDot, sineDot);
scene.add(title, thetaLabel, sinLabel);

updateVisuals();

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({
  label: 'Angle θ',
  min: 0,
  max: 2 * Math.PI,
  value: theta,
  step: 0.01,
  onChange: (val) => {
    theta = val;
    updateVisuals();
  }
});
controls.addButton({
  label: 'Spin once',
  onClick: async () => {
    const start = theta;
    const tracker = new ValueTracker(start);
    tracker.addUpdater(() => {
      theta = tracker.getValue();
      updateVisuals();
    });
    await scene.play(tracker.animateTo(start + 2 * Math.PI, { duration: 3 }));
    tracker.clearUpdaters();
    theta = ((theta % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
    updateVisuals();
  }
});

await scene.wait(999999);"
